// Initialize execution context with timezone awareness
const now = new Date();

// Configuration (can be moved to environment variables)
const config = {
  timezone: 'America/New_York',
  businessHours: {
    start: 9,
    end: 17,
    days: [1, 2, 3, 4, 5] // Monday-Friday
  },
  holidays: [
    '2025-01-01', // New Year's Day
    '2025-12-25', // Christmas
    '2025-07-04', // Independence Day
    // Add more holidays as needed
  ],
  catchUpEnabled: true,
  maxCatchUpRuns: 5
};

// Get current time in target timezone
const options = { timeZone: config.timezone, hour12: false };
const localTime = now.toLocaleString('en-US', options);
const localDate = now.toLocaleDateString('en-CA', { timeZone: config.timezone });
const localHour = parseInt(now.toLocaleString('en-US', { ...options, hour: '2-digit' }));
const localDay = now.toLocaleDateString('en-US', { timeZone: config.timezone, weekday: 'long' });
const dayOfWeek = new Date(localDate).getDay();

// Check if today is a holiday
const isHoliday = config.holidays.includes(localDate);

// Check if within business hours
const isBusinessDay = config.businessHours.days.includes(dayOfWeek);
const isBusinessHour = localHour >= config.businessHours.start && localHour < config.businessHours.end;
const isBusinessTime = isBusinessDay && isBusinessHour && !isHoliday;

// Execution metadata
const executionMeta = {
  executionId: `exec_${Date.now()}`,
  scheduledAt: now.toISOString(),
  localTime,
  localDate,
  dayOfWeek: localDay,
  timezone: config.timezone,
  isBusinessTime,
  isHoliday,
  config
};

return [{ json: executionMeta }];

// Execute the main scheduled task
// This is where your actual automation logic goes
const context = $input.first().json;

console.log(`Executing scheduled task at ${context.localTime}`);

// Simulated task execution - replace with actual logic
const taskResult = {
  ...context,
  task: {
    name: 'Daily Report Generation',
    status: 'completed',
    startedAt: new Date().toISOString(),
    result: {
      recordsProcessed: Math.floor(Math.random() * 1000) + 100,
      reportsGenerated: Math.floor(Math.random() * 10) + 1
    }
  }
};

taskResult.task.completedAt = new Date().toISOString();
taskResult.task.duration = Date.now() - new Date(taskResult.scheduledAt).getTime();

return [{ json: taskResult }];

// Handle deferral for non-business hours
const context = $input.first().json;

// Calculate next business hour
const nextBusinessTime = () => {
  const now = new Date();
  const config = context.config;

  // Find next valid execution time
  let candidate = new Date(now);
  candidate.setHours(config.businessHours.start, 0, 0, 0);

  // If past start time today, move to tomorrow
  if (now.getHours() >= config.businessHours.start) {
    candidate.setDate(candidate.getDate() + 1);
  }

  // Skip weekends
  while (!config.businessHours.days.includes(candidate.getDay())) {
    candidate.setDate(candidate.getDate() + 1);
  }

  // Skip holidays (simplified check)
  const candidateDate = candidate.toISOString().split('T')[0];
  while (config.holidays.includes(candidateDate)) {
    candidate.setDate(candidate.getDate() + 1);
  }

  return candidate.toISOString();
};

const deferral = {
  ...context,
  deferred: true,
  reason: context.isHoliday ? 'holiday' : 'outside_business_hours',
  nextAttempt: nextBusinessTime(),
  deferredAt: new Date().toISOString()
};

return [{ json: deferral }];

// Check for missed executions and catch up if enabled
const context = $input.first().json;
const staticData = $workflow.staticData;

// Initialize static data
if (!staticData.lastExecution) {
  staticData.lastExecution = new Date().toISOString();
  staticData.missedExecutions = [];
}

const lastExec = new Date(staticData.lastExecution);
const now = new Date();
const hoursSinceLastExec = (now - lastExec) / (1000 * 60 * 60);

// Check if we missed any scheduled runs (assuming hourly schedule)
const missedRuns = Math.floor(hoursSinceLastExec) - 1;
const shouldCatchUp = context.config.catchUpEnabled && missedRuns > 0;

if (shouldCatchUp) {
  const catchUpCount = Math.min(missedRuns, context.config.maxCatchUpRuns);

  for (let i = 0; i < catchUpCount; i++) {
    staticData.missedExecutions.push({
      scheduledFor: new Date(lastExec.getTime() + (i + 1) * 60 * 60 * 1000).toISOString(),
      catchUpAt: now.toISOString()
    });
  }
}

// Update last execution time
staticData.lastExecution = now.toISOString();

return [{
  json: {
    ...context,
    catchUp: {
      enabled: context.config.catchUpEnabled,
      missedRuns,
      catchUpRuns: shouldCatchUp ? Math.min(missedRuns, context.config.maxCatchUpRuns) : 0,
      history: staticData.missedExecutions.slice(-10)
    }
  }
}];

// Log execution for monitoring
const result = $input.first().json;

const logEntry = {
  type: result.deferred ? 'deferred' : 'executed',
  executionId: result.executionId,
  timestamp: new Date().toISOString(),
  localTime: result.localTime,
  timezone: result.timezone,
  task: result.task || null,
  deferred: result.deferred || false,
  reason: result.reason || null,
  nextAttempt: result.nextAttempt || null,
  catchUp: result.catchUp || null
};

// In production, send to logging service or database
console.log('Execution Log:', JSON.stringify(logEntry, null, 2));

return [{ json: logEntry }];
